MASK_EDITOR_MARKUP = r"""
<section id="mask-editor" class="mask-editor" hidden aria-labelledby="mask-editor-title">
<h4 id="mask-editor-title">手工修正商品边界</h4><p class="mask-editor-note">魔棒删除连在一起的多余区域；画笔可擦除或恢复。修正只改遮罩，不会重画商品。</p>
<div id="mask-editor-layers" class="mask-editor-layers" role="tablist" aria-label="金标图层" hidden></div><p class="mask-editor-layer-copy">当前图层：<strong id="mask-editor-layer-name">整体商品</strong>。关键部件必须完整落在整体商品范围内。</p>
<div class="mask-editor-toolbar" role="toolbar" aria-label="遮罩修正工具"><button type="button" data-mask-tool="wand" aria-pressed="true">魔棒</button><button type="button" data-mask-tool="erase" aria-pressed="false">擦除</button><button type="button" data-mask-tool="restore" aria-pressed="false">恢复</button><button type="button" id="mask-pan" aria-pressed="false">移动画布</button><label>画笔大小 <input id="mask-brush-size" type="range" min="1" max="80" value="12"></label><label>缩放 <input id="mask-zoom" type="range" min="25" max="300" value="100"></label><button type="button" id="mask-undo">撤销</button><button type="button" id="mask-redo">重做</button><button type="button" id="mask-reset">恢复自动遮罩</button></div>
<div id="mask-editor-viewport" class="mask-editor-viewport"><canvas id="mask-editor-canvas" aria-label="可修正的商品遮罩"></canvas></div><div id="mask-editor-status" class="status-line" aria-live="polite">正在读取遮罩…</div><div class="pixel-actions"><button id="mask-save" type="button" class="primary" disabled>保存为新版本</button><button id="mask-close" type="button">关闭编辑</button></div>
</section>
""".strip()

MASK_EDITOR_UI_SCRIPT = r"""
/* mask-editor-ui-contract:start */
function maskEditorSavedState(state,sessionId,version){if(!state||state.sessionId!==sessionId)return null;return{...state,version,confirmed:false,generationLocked:true,draftClearKey:state.draftKey||null}}
function maskEditorDraftKey(scope){return['opcMaskDraftV1',scope.customerId,scope.assetId,scope.baseVersionId,scope.sourceSha256,scope.baseMaskSha256,scope.editorVersion].join(':')}
function maskEditorDraftMatches(draft,scope){if(!draft||!draft.scope)return false;return['customerId','assetId','baseVersionId','sourceSha256','baseMaskSha256','editorVersion'].every(key=>draft.scope[key]===scope[key])}
function maskEditorDraftFailureState(state){return{...state,warning:'本次修改仍可保存，但刷新后无法恢复。'}}
function maskEditorFitZoom(width,height,viewportWidth,viewportHeight){const ratio=Math.min(1,viewportWidth/width,viewportHeight/height);return Math.max(25,Math.min(100,Math.floor(ratio*100)))}
/* mask-editor-ui-contract:end */
const editForegroundMask=document.querySelector('#edit-foreground-mask'),maskEditor=document.querySelector('#mask-editor'),maskEditorCanvas=document.querySelector('#mask-editor-canvas'),maskEditorViewport=document.querySelector('#mask-editor-viewport'),maskEditorStatus=document.querySelector('#mask-editor-status'),maskEditorLayers=document.querySelector('#mask-editor-layers'),maskEditorLayerName=document.querySelector('#mask-editor-layer-name'),maskBrushSize=document.querySelector('#mask-brush-size'),maskZoom=document.querySelector('#mask-zoom'),maskPan=document.querySelector('#mask-pan'),maskUndo=document.querySelector('#mask-undo'),maskRedo=document.querySelector('#mask-redo'),maskReset=document.querySelector('#mask-reset'),maskSave=document.querySelector('#mask-save'),maskClose=document.querySelector('#mask-close');
let maskEditorState=null,maskEditorOriginalBitmap=null,maskEditorStroke=null;
function openMaskEditorDraftDatabase(){return new Promise((resolve,reject)=>{if(!globalThis.indexedDB){reject(Error('indexeddb_unavailable'));return}const request=indexedDB.open('opc-style-mask-editor',1);request.onupgradeneeded=()=>{if(!request.result.objectStoreNames.contains('drafts'))request.result.createObjectStore('drafts',{keyPath:'key'})};request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error||Error('indexeddb_open_failed'))})}
async function maskEditorDraftOperation(mode,key,value){const database=await openMaskEditorDraftDatabase();try{return await new Promise((resolve,reject)=>{const transaction=database.transaction('drafts',mode==='read'?'readonly':'readwrite'),store=transaction.objectStore('drafts'),request=mode==='read'?store.get(key):mode==='write'?store.put(value):store.delete(key);request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error||Error('indexeddb_request_failed'));transaction.onabort=()=>reject(transaction.error||Error('indexeddb_transaction_failed'))})}finally{database.close()}}
function readMaskEditorDraft(key){return maskEditorDraftOperation('read',key)}
function writeMaskEditorDraft(draft){return maskEditorDraftOperation('write',draft.key,draft)}
function deleteMaskEditorDraft(key){return maskEditorDraftOperation('delete',key)}
function maskEditorScope(version){return{customerId,assetId:asset.id,baseVersionId:version.id,sourceSha256:version.source_content_sha256,baseMaskSha256:version.mask_sha256,editorVersion:'human-mask-editor-v2'}}
async function maskEditorFetchBitmap(url){const response=await fetch(url,{headers});if(!response.ok)throw httpStatusError(response.status);return createImageBitmap(await response.blob())}
async function maskEditorLoadMask(url,width,height){const bitmap=await maskEditorFetchBitmap(url);try{const canvas=document.createElement('canvas');canvas.width=width;canvas.height=height;const context=canvas.getContext('2d',{willReadFrequently:true});context.drawImage(bitmap,0,0,width,height);const pixels=context.getImageData(0,0,width,height).data,mask=new Uint8Array(width*height);for(let index=0;index<mask.length;index++)mask[index]=pixels[index*4]>=128?255:0;return mask}finally{bitmap.close()}}
function maskEditorRender(){if(!maskEditorState||!maskEditorOriginalBitmap)return;const{width,height}=maskEditorState,layerSet=maskEditorState.layers,layer=layerSet.current(),context=maskEditorCanvas.getContext('2d');maskEditorCanvas.width=width;maskEditorCanvas.height=height;context.clearRect(0,0,width,height);context.drawImage(maskEditorOriginalBitmap,0,0,width,height);const overlayCanvas=document.createElement('canvas');overlayCanvas.width=width;overlayCanvas.height=height;const overlayContext=overlayCanvas.getContext('2d'),overlay=overlayContext.createImageData(width,height);for(let index=0;index<layer.mask.length;index++){if(layer.mask[index]){overlay.data[index*4]=181;overlay.data[index*4+1]=138;overlay.data[index*4+2]=82;overlay.data[index*4+3]=105}}overlayContext.putImageData(overlay,0,0);context.drawImage(overlayCanvas,0,0);const zoom=Number(maskZoom.value)/100;maskEditorCanvas.style.width=`${width*zoom}px`;maskEditorCanvas.style.height=`${height*zoom}px`;const state=maskEditorState,allowUnchanged=state.target.kind==='workbench-gold'&&Boolean(state.target.maskUrl),metrics=maskEditorMetrics(layer.baseMask,layer.mask,width,height),gate=state.target.kind==='workbench-gold'?maskEditorLayerSaveGate(layerSet,width,height,state.busy,allowUnchanged):maskEditorSaveGate(metrics,state.busy,false);maskSave.disabled=!gate.canSave;maskSave.textContent=state.target.kind==='workbench-gold'?'保存全部金标':'保存为新版本';maskEditorStatus.className=`status-line ${metrics.largeChangeWarning?'mask-editor-warning':''}`;maskEditorStatus.textContent=state.recoveryWarning?`${gate.message}；${state.recoveryWarning}`:gate.message;maskEditorLayerName.textContent=maskEditorLayerLabel(layer.name);maskEditorLayers.querySelectorAll('button').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.maskLayer===layer.name)));maskUndo.disabled=!layer.history.canUndo()||state.busy;maskRedo.disabled=!layer.history.canRedo()||state.busy}
async function maskEditorPersistDraft(){if(!maskEditorState)return;const state=maskEditorState,draft={key:state.draftKey,scope:state.scope,layerSnapshot:state.layers.snapshot(),updatedAt:new Date().toISOString()};try{await writeMaskEditorDraft(draft)}catch(error){if(maskEditorState===state){state.recoveryWarning=maskEditorDraftFailureState({}).warning;maskEditorRender()}}}
function maskEditorCommit(nextMask,operation){if(!maskEditorState||!maskEditorState.layers.commit(nextMask,operation))return false;maskEditorRender();maskEditorPersistDraft();return true}
function maskEditorSelectLayer(name){if(!maskEditorState)return;const layer=maskEditorState.layers.select(name);selectMaskEditorTool(name==='overall'&&maskEditorState.target.maskUrl?'wand':'restore');maskEditorRender();return layer}
function maskEditorRenderLayerButtons(){maskEditorLayers.replaceChildren();if(!maskEditorState||maskEditorState.layers.names().length===1){maskEditorLayers.hidden=true;return}maskEditorLayers.hidden=false;for(const name of maskEditorState.layers.names()){const button=document.createElement('button');button.type='button';button.dataset.maskLayer=name;button.setAttribute('role','tab');button.textContent=maskEditorLayerLabel(name);button.onclick=()=>maskEditorSelectLayer(name);maskEditorLayers.append(button)}}
function selectMaskEditorTool(tool){if(!maskEditorState)return;maskEditorState.tool=tool;document.querySelectorAll('[data-mask-tool]').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.maskTool===tool)));maskPan.setAttribute('aria-pressed',String(tool==='pan'))}
function maskEditorPoint(event){if(!maskEditorState)return null;return maskEditorSourcePoint(event.clientX,event.clientY,maskEditorCanvas.getBoundingClientRect(),maskEditorState.width,maskEditorState.height,{zoom:1,panX:0,panY:0})}
function beginMaskEditorStroke(event){if(!maskEditorState||maskEditorState.busy)return;event.preventDefault();maskEditorCanvas.setPointerCapture(event.pointerId);if(maskEditorState.tool==='pan'){maskEditorStroke={kind:'pan',pointerId:event.pointerId,clientX:event.clientX,clientY:event.clientY,scrollLeft:maskEditorViewport.scrollLeft,scrollTop:maskEditorViewport.scrollTop};return}const point=maskEditorPoint(event);if(!point)return;const layer=maskEditorState.layers.current();if(maskEditorState.tool==='wand'){const changed=maskEditorFloodErase(layer.mask,maskEditorState.width,maskEditorState.height,point.x,point.y);maskEditorCommit(changed.mask,'magic_wand_count');return}const start=layer.mask.slice(),value=maskEditorState.tool==='restore'?255:0,result=maskEditorBrush(start,maskEditorState.width,maskEditorState.height,point,point,Number(maskBrushSize.value)/2,value);layer.mask=result.mask;maskEditorStroke={kind:'brush',pointerId:event.pointerId,last:point,start,changed:result.changed};maskEditorRender()}
function moveMaskEditorStroke(event){if(!maskEditorState||!maskEditorStroke||maskEditorStroke.pointerId!==event.pointerId)return;event.preventDefault();if(maskEditorStroke.kind==='pan'){maskEditorViewport.scrollLeft=maskEditorStroke.scrollLeft-(event.clientX-maskEditorStroke.clientX);maskEditorViewport.scrollTop=maskEditorStroke.scrollTop-(event.clientY-maskEditorStroke.clientY);return}const point=maskEditorPoint(event);if(!point)return;const layer=maskEditorState.layers.current(),value=maskEditorState.tool==='restore'?255:0,result=maskEditorBrush(layer.mask,maskEditorState.width,maskEditorState.height,maskEditorStroke.last,point,Number(maskBrushSize.value)/2,value);layer.mask=result.mask;maskEditorStroke.last=point;maskEditorStroke.changed=maskEditorStroke.changed||result.changed;maskEditorRender()}
function endMaskEditorStroke(event){if(!maskEditorState||!maskEditorStroke||maskEditorStroke.pointerId!==event.pointerId)return;event.preventDefault();const stroke=maskEditorStroke;maskEditorStroke=null;if(stroke.kind!=='brush'||!stroke.changed)return;const layer=maskEditorState.layers.current(),result=layer.mask.slice();layer.mask=stroke.start;const operation=maskEditorState.tool==='restore'?'restore_stroke_count':'erase_stroke_count';maskEditorCommit(result,operation)}
function cancelMaskEditorStroke(event){endMaskEditorStroke(event)}
function closeMaskEditor(){maskEditor.hidden=true;maskEditorStroke=null;maskEditorLayers.replaceChildren();maskEditorLayers.hidden=true;if(maskEditorOriginalBitmap){maskEditorOriginalBitmap.close();maskEditorOriginalBitmap=null}maskEditorState=null}
async function openMaskEditorForTarget(target){closeMaskEditor();const sessionId=crypto.randomUUID(),scope=target.scope,draftKey=maskEditorDraftKey(scope);maskEditor.hidden=false;maskEditorStatus.textContent='正在读取遮罩…';try{const componentNames=target.kind==='workbench-gold'?target.sample.critical_component_names:[],savedComponentNames=new Set(target.kind==='workbench-gold'?Object.keys(target.sample.component_mask_sha256s||{}):[]),componentPromises=componentNames.map(async name=>[name,savedComponentNames.has(name)?await maskEditorLoadMask(`${benchmarkBase}/datasets/${benchmarkDataset.dataset_id}/samples/${target.sample.sample_id}/mask?kind=component&component_name=${encodeURIComponent(name)}`,target.width,target.height):new Uint8Array(target.width*target.height)]),originalPromise=maskEditorFetchBitmap(target.originalUrl),maskPromise=target.maskUrl?maskEditorLoadMask(target.maskUrl,target.width,target.height):Promise.resolve(new Uint8Array(target.width*target.height)),[original,baseMask,componentEntries]=await Promise.all([originalPromise,maskPromise,Promise.all(componentPromises)]),componentBaseMasks=Object.fromEntries(componentEntries);maskEditorOriginalBitmap=original;const layers=createMaskEditorLayerSet(baseMask,componentNames,50,componentBaseMasks);maskEditorState={target,sessionId,scope,draftKey,width:target.width,height:target.height,layers,tool:target.maskUrl?'wand':'restore',busy:false,recoveryWarning:''};try{const draft=await readMaskEditorDraft(draftKey);if(maskEditorDraftMatches(draft,scope))layers.restore(draft.layerSnapshot)}catch(error){maskEditorState.recoveryWarning=maskEditorDraftFailureState({}).warning}maskEditorRenderLayerButtons();selectMaskEditorTool(maskEditorState.layers.activeName()==='overall'&&target.maskUrl?'wand':'restore');maskZoom.value=String(maskEditorFitZoom(target.width,target.height,maskEditorViewport.clientWidth||680,520));maskEditorRender();maskEditor.scrollIntoView({behavior:'smooth',block:'start'})}catch(error){maskEditorStatus.className='status-line mask-editor-error';maskEditorStatus.textContent='遮罩编辑器打开失败：'+error.message}}
async function openMaskEditor(){if(!foregroundPreview||!asset)return;const version=foregroundPreview;await openMaskEditorForTarget({kind:'product',width:version.width,height:version.height,originalUrl:`/local/style-suite/api/assets/${asset.id}/content`,maskUrl:version.mask_content_url,version,scope:maskEditorScope(version)})}
async function maskEditorEditManifest(version,resultMaskPixelsSha256,counts){return maskEditorManifestSha256({asset_id:asset.id,base_manifest_sha256:version.manifest_sha256,base_mask_sha256:version.mask_sha256,base_version_id:version.id,customer_id:customerId,editor_version:'human-mask-editor-v1',erase_stroke_count:counts.erase_stroke_count,magic_wand_count:counts.magic_wand_count,restore_stroke_count:counts.restore_stroke_count,result_mask_pixels_sha256:resultMaskPixelsSha256,source_content_sha256:version.source_content_sha256})}
async function saveProductMaskEditor(state,blob){const version=state.target.version,sessionId=state.sessionId,overall=state.layers.get('overall'),pixelDigest=await maskEditorSha256(overall.mask),manifest=await maskEditorEditManifest(version,pixelDigest,overall.counts),form=new FormData();form.append('mask',blob,'mask.png');form.append('base_version_id',version.id);form.append('base_manifest_sha256',version.manifest_sha256);form.append('edit_manifest_sha256',manifest);form.append('editor_version','human-mask-editor-v1');form.append('idempotency_key',`browser-mask-edit-${version.id}-${sessionId}`);form.append('magic_wand_count',String(overall.counts.magic_wand_count));form.append('erase_stroke_count',String(overall.counts.erase_stroke_count));form.append('restore_stroke_count',String(overall.counts.restore_stroke_count));const saved=await json(`/local/style-suite/api/products/${asset.id}/foreground-edits`,{method:'POST',body:form}),next=maskEditorSavedState(state,sessionId,saved);if(!next||maskEditorState!==state)return;confirmedForeground=undefined;foregroundConfirmation.checked=false;closeMaskEditor();renderForegroundVersion(saved);foregroundStatus.textContent=`已保存修正版 v${saved.version}，请重新核对三张图并确认。`;updatePilotEnabled()}
async function saveWorkbenchGoldMask(state,blob,componentBlobs){const sample=state.target.sample,form=new FormData();form.append('expected_revision',String(benchmarkDataset.revision));form.append('gold_mask',blob,'gold-mask.png');sample.critical_component_names.forEach(name=>{form.append('component_names',name);form.append('component_masks',componentBlobs.get(name),`${name}-mask.png`)});benchmarkDataset=await json(`${benchmarkBase}/datasets/${benchmarkDataset.dataset_id}/samples/${sample.sample_id}/gold-mask`,{method:'POST',body:form});closeMaskEditor();renderBenchmark();benchmarkUploadStatus.className='status-line success-note';benchmarkUploadStatus.textContent='整体与关键部件金标已保存；请继续确认人工金标。'}
async function saveMaskEditor(){if(!maskEditorState||maskEditorState.busy)return;const state=maskEditorState,overall=state.layers.get('overall'),allowUnchanged=state.target.kind==='workbench-gold'&&Boolean(state.target.maskUrl),gate=state.target.kind==='workbench-gold'?maskEditorLayerSaveGate(state.layers,state.width,state.height,false,allowUnchanged):maskEditorSaveGate(maskEditorMetrics(overall.baseMask,overall.mask,state.width,state.height),false,false);if(!gate.canSave)return;state.busy=true;maskEditorRender();try{const blob=await maskEditorMaskPngBlob(overall.mask,state.width,state.height);if(state.target.kind==='workbench-gold'){const componentBlobs=new Map;for(const name of state.layers.names().slice(1))componentBlobs.set(name,await maskEditorMaskPngBlob(state.layers.get(name).mask,state.width,state.height));await saveWorkbenchGoldMask(state,blob,componentBlobs)}else await saveProductMaskEditor(state,blob);try{await deleteMaskEditorDraft(state.draftKey)}catch(error){}}catch(error){if(maskEditorState===state){state.busy=false;maskEditorStatus.className='status-line mask-editor-error';maskEditorStatus.textContent='保存未完成，本地修改已保留：'+error.message;maskEditorRender()}}}
function maskEditorOnForegroundVersion(version){editForegroundMask.hidden=!version||!asset;editForegroundMask.disabled=!version}
document.querySelectorAll('[data-mask-tool]').forEach(button=>button.onclick=()=>selectMaskEditorTool(button.dataset.maskTool));maskPan.onclick=()=>selectMaskEditorTool('pan');maskZoom.oninput=maskEditorRender;maskUndo.onclick=()=>{if(!maskEditorState)return;maskEditorState.layers.undo();maskEditorRender();maskEditorPersistDraft()};maskRedo.onclick=()=>{if(!maskEditorState)return;maskEditorState.layers.redo();maskEditorRender();maskEditorPersistDraft()};maskReset.onclick=()=>{if(!maskEditorState)return;if(maskEditorState.layers.reset()){maskEditorRender();maskEditorPersistDraft()}};maskSave.onclick=saveMaskEditor;maskClose.onclick=closeMaskEditor;editForegroundMask.onclick=openMaskEditor;maskEditorCanvas.onpointerdown=beginMaskEditorStroke;maskEditorCanvas.onpointermove=moveMaskEditorStroke;maskEditorCanvas.onpointerup=endMaskEditorStroke;maskEditorCanvas.onpointercancel=endMaskEditorStroke;
""".strip()
